use std::fs
use std::env

fn pad(n: int) -> string {
    let s = n.to_string()
    let mut out = ""
    let mut i = s.len()
    while i < 6 {
        out = out + " "
        i = i + 1
    }
    out + s
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    for a in env::args().skip(1) {
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    if files.len() == 0 {
        files.push("/dev/stdin")
    }
    let mut counter = 0
    let mut failed = false
    for f in files {
        match fs::read_to_string(f.clone()) {
            Ok(text) => {
                if number {
                    for line in text.lines() {
                        counter = counter + 1
                        println(pad(counter) + "\t" + line)
                    }
                } else {
                    print(text)
                }
            }
            Err(_) => {
                println("cat: " + f + ": No such file")
                failed = true
            }
        }
    }
    if failed {
        std::process::exit(1)
    }
}

